use serde::{Deserialize, Serialize};
use std::collections::HashMap;

mkdeclimpl! {
impl AttributeExt for Attribute { fn id (& self) -> AttrId { self . id } fn value_span (& self) -> Option < Span > { match & self . kind { AttrKind :: Normal (normal) => match & normal . item . args { AttrArgs :: Eq { expr , .. } => Some (expr . span) , _ => None , } , AttrKind :: DocComment (..) => None , } } # [doc = " Returns `true` if it is a sugared doc comment (`///` or `//!` for example)."] # [doc = " So `#[doc = \"doc\"]` (which is a doc comment) and `#[doc(...)]` (which is not"] # [doc = " a doc comment) will return `false`."] fn is_doc_comment (& self) -> bool { match self . kind { AttrKind :: Normal (..) => false , AttrKind :: DocComment (..) => true , } } # [doc = " For a single-segment attribute, returns its name; otherwise, returns `None`."] fn ident (& self) -> Option < Ident > { match & self . kind { AttrKind :: Normal (normal) => { if let [ident] = & * normal . item . path . segments { Some (ident . ident) } else { None } } AttrKind :: DocComment (..) => None , } } fn ident_path (& self) -> Option < SmallVec < [Ident ; 1] > > { match & self . kind { AttrKind :: Normal (p) => Some (p . item . path . segments . iter () . map (| i | i . ident) . collect ()) , AttrKind :: DocComment (_ , _) => None , } } fn path_matches (& self , name : & [Symbol]) -> bool { match & self . kind { AttrKind :: Normal (normal) => { normal . item . path . segments . len () == name . len () && normal . item . path . segments . iter () . zip (name) . all (| (s , n) | s . args . is_none () && s . ident . name == * n) } AttrKind :: DocComment (..) => false , } } fn span (& self) -> Span { self . span } fn is_word (& self) -> bool { if let AttrKind :: Normal (normal) = & self . kind { matches ! (normal . item . args , AttrArgs :: Empty) } else { false } } # [doc = " Returns a list of meta items if the attribute is delimited with parenthesis:"] # [doc = ""] # [doc = " ```text"] # [doc = " #[attr(a, b = \"c\")] // Returns `Some()`."] # [doc = " #[attr = \"\"] // Returns `None`."] # [doc = " #[attr] // Returns `None`."] # [doc = " ```"] fn meta_item_list (& self) -> Option < ThinVec < MetaItemInner > > { match & self . kind { AttrKind :: Normal (normal) => normal . item . meta_item_list () , AttrKind :: DocComment (..) => None , } } # [doc = " Returns the string value in:"] # [doc = ""] # [doc = " ```text"] # [doc = " #[attribute = \"value\"]"] # [doc = "               ^^^^^^^"] # [doc = " ```"] # [doc = ""] # [doc = " It returns `None` in any other cases, including doc comments if they"] # [doc = " are not under the form `#[doc = \"...\"]`."] # [doc = ""] # [doc = " It also returns `None` for:"] # [doc = ""] # [doc = " ```text"] # [doc = " #[attr(\"value\")]"] # [doc = " ```"] fn value_str (& self) -> Option < Symbol > { match & self . kind { AttrKind :: Normal (normal) => normal . item . value_str () , AttrKind :: DocComment (..) => None , } } # [doc = " Returns the documentation and its kind if this is a doc comment or a sugared doc comment."] # [doc = " * `///doc` returns `Some((\"doc\", CommentKind::Line))`."] # [doc = " * `/** doc */` returns `Some((\"doc\", CommentKind::Block))`."] # [doc = " * `#[doc = \"doc\"]` returns `Some((\"doc\", CommentKind::Line))`."] # [doc = " * `#[doc(...)]` returns `None`."] fn doc_str_and_comment_kind (& self) -> Option < (Symbol , CommentKind) > { match & self . kind { AttrKind :: DocComment (kind , data) => Some ((* data , * kind)) , AttrKind :: Normal (normal) if normal . item . path == sym :: doc => { normal . item . value_str () . map (| s | (s , CommentKind :: Line)) } _ => None , } } # [doc = " Returns the documentation if this is a doc comment or a sugared doc comment."] # [doc = " * `///doc` returns `Some(\"doc\")`."] # [doc = " * `#[doc = \"doc\"]` returns `Some(\"doc\")`."] # [doc = " * `#[doc(...)]` returns `None`."] fn doc_str (& self) -> Option < Symbol > { match & self . kind { AttrKind :: DocComment (.. , data) => Some (* data) , AttrKind :: Normal (normal) if normal . item . path == sym :: doc => normal . item . value_str () , _ => None , } } fn doc_resolution_scope (& self) -> Option < AttrStyle > { match & self . kind { AttrKind :: DocComment (..) => Some (self . style) , AttrKind :: Normal (normal) if normal . item . path == sym :: doc && normal . item . value_str () . is_some () => { Some (self . style) } _ => None , } } fn is_automatically_derived_attr (& self) -> bool { self . has_name (sym :: automatically_derived) } }
}